1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.Moeda;
4	import com.loja.checkout.domain.Regiao;
5	import com.loja.checkout.domain.clube.NivelClube;
6	import com.loja.checkout.domain.cupom.Cupom;
7	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
8	import com.loja.checkout.domain.pagamento.FormaPagamento;
9	import com.loja.checkout.domain.pagamento.ResultadoPagamento;
10	import com.loja.checkout.dto.ItemRequest;
11	import com.loja.checkout.dto.ResumoRequest;
12	import com.loja.checkout.dto.ResumoResponse;
13	import com.loja.checkout.exception.CheckoutException;
14	import org.springframework.stereotype.Service;
15	
16	import java.math.BigDecimal;
17	import java.util.List;
18	import java.util.Map;
19	import java.util.function.Function;
20	import java.util.stream.Collectors;
21	
22	@Service
23	public class CheckoutService {
24	
25	    private final Map<String, ModalidadeEntrega> modalidades;
26	    private final Map<String, Cupom> cupons;
27	    private final Map<String, NivelClube> niveisClube;
28	    private final Map<String, FormaPagamento> formasPagamento;
29	
30	    public CheckoutService(List<ModalidadeEntrega> modalidades,
31	                           List<Cupom> cupons,
32	                           List<NivelClube> niveisClube,
33	                           List<FormaPagamento> formasPagamento) {
34	        this.modalidades = indexar(modalidades, ModalidadeEntrega::codigo);
35	        this.cupons = indexar(cupons, Cupom::codigo);
36	        this.niveisClube = indexar(niveisClube, NivelClube::codigo);
37	        this.formasPagamento = indexar(formasPagamento, FormaPagamento::codigo);
38	    }
39	
40	    public ResumoResponse calcular(ResumoRequest req) {
41	        validarItens(req.itens());
42	
43	        BigDecimal subtotal = calcularSubtotal(req.itens());
44	        BigDecimal pesoTotal = calcularPeso(req.itens());
45	
46	        NivelClube nivel = buscar(niveisClube, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
47	
48	        Regiao regiao = Regiao.buscar(req.regiao())
49	                .orElseThrow(() -> new CheckoutException("REGIAO_INVALIDA"));
50	
51	        ModalidadeEntrega modalidade = buscar(modalidades, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
52	
53	        if (!modalidade.disponivel(pesoTotal)) {
54	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
55	        }
56	
57	        BigDecimal frete = nivel.freteGratis()
58	                ? BigDecimal.ZERO.setScale(2)
59	                : modalidade.calcularFrete(pesoTotal);
60	
61	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
62	        if (req.cupom() != null && !req.cupom().isEmpty()) {
63	            Cupom cupom = buscar(cupons, req.cupom(), "CUPOM_INVALIDO");
64	            if (!cupom.aplicavel(req.itens(), subtotal, frete)) {
65	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
66	            }
67	            descontoCupom = cupom.calcularDesconto(req.itens(), subtotal, frete);
68	        }
69	
70	        int parcelas = req.parcelas() != null ? req.parcelas() : 1;
71	        FormaPagamento pagamento = buscar(formasPagamento, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
72	
73	        if (!pagamento.parcelasValidas(parcelas)) {
74	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
75	        }
76	
77	        BigDecimal seguro = regiao.calcularSeguro(subtotal);
78	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
79	
80	        if (!pagamento.disponivel(totalPedido)) {
81	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
82	        }
83	
84	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
85	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido);
86	
87	        return new ResumoResponse(
88	                subtotal,
89	                descontoCupom,
90	                frete,
91	                modalidade.prazoDias(),
92	                seguro,
93	                ajuste,
94	                resultado.totalFinal(),
95	                parcelas,
96	                resultado.valorParcela(),
97	                nivel.calcularCredito(subtotal),
98	                nivel.brinde(subtotal));
99	    }
100	
101	    private void validarItens(List<ItemRequest> itens) {
102	        if (itens == null || itens.isEmpty()) {
103	            throw new CheckoutException("PEDIDO_INVALIDO");
104	        }
105	        for (ItemRequest item : itens) {
106	            if (item == null
107	                    || item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
108	                    || item.quantidade() == null || item.quantidade() <= 0
109	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
110	                throw new CheckoutException("PEDIDO_INVALIDO");
111	            }
112	        }
113	    }
114	
115	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
116	        BigDecimal subtotal = BigDecimal.ZERO;
117	        for (ItemRequest item : itens) {
118	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
119	        }
120	        return Moeda.arredondar(subtotal);
121	    }
122	
123	    private BigDecimal calcularPeso(List<ItemRequest> itens) {
124	        BigDecimal peso = BigDecimal.ZERO;
125	        for (ItemRequest item : itens) {
126	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
127	        }
128	        return peso;
129	    }
130	
131	    private static <T> T buscar(Map<String, T> mapa, String codigo, String codigoErro) {
132	        if (codigo == null) throw new CheckoutException(codigoErro);
133	        T valor = mapa.get(codigo);
134	        if (valor == null) throw new CheckoutException(codigoErro);
135	        return valor;
136	    }
137	
138	    private static <T> Map<String, T> indexar(List<T> lista, Function<T, String> chave) {
139	        return lista.stream().collect(Collectors.toMap(chave, Function.identity()));
140	    }
141	}
