1	package com.loja.checkout.domain.pagamento;
2	
3	import com.loja.checkout.domain.Moeda;
4	import org.springframework.stereotype.Component;
5	
6	import java.math.BigDecimal;
7	import java.math.RoundingMode;
8	
9	@Component
10	public class Cartao implements FormaPagamento {
11	
12	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
13	    private static final int MAX_SEM_JUROS = 3;
14	    private static final int MAX_PARCELAS = 12;
15	
16	    @Override
17	    public String codigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean parcelasValidas(int parcelas) {
23	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
24	    }
25	
26	    @Override
27	    public boolean disponivel(BigDecimal totalPedido) {
28	        return true;
29	    }
30	
31	    @Override
32	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
33	        if (parcelas <= MAX_SEM_JUROS) {
34	            BigDecimal valorParcela = Moeda.arredondar(
35	                    totalPedido.divide(BigDecimal.valueOf(parcelas), 10, RoundingMode.HALF_EVEN));
36	            return new ResultadoPagamento(totalPedido, valorParcela);
37	        }
38	
39	        double taxa = TAXA_MENSAL.doubleValue();
40	        double fator = Math.pow(1 + taxa, -parcelas);
41	        BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.valueOf(fator));
42	        BigDecimal numerador = totalPedido.multiply(TAXA_MENSAL);
43	        BigDecimal valorParcela = Moeda.arredondar(
44	                numerador.divide(denominador, 10, RoundingMode.HALF_EVEN));
45	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
46	        return new ResultadoPagamento(totalFinal, valorParcela);
47	    }
48	}
